# test_eintritt_ut.py
import unittest
from eintritt import preis

class TestPreis(unittest.TestCase):
    def test_kind_gratis(self):
        self.assertEqual(preis(5), 0.0)

    def test_jugendlich(self):
        self.assertEqual(preis(6), 4.5)

    def test_negativ(self):
        with self.assertRaises(ValueError):
            preis(-1)

# test_eintritt.py
import pytest
from eintritt import preis

@pytest.mark.parametrize("alter, erwartet", [
    (0, 0.0), (5, 0.0),
    (6, 4.5), (17, 4.5),
    (18, 9.0),
])
def test_preis(alter, erwartet):
    assert preis(alter) == erwartet

def test_negativ():
    with pytest.raises(ValueError):
        preis(-1)

