import pytest

def quadrat(x):
    return x * x

@pytest.mark.parametrize("x, e", [
    (2, 4), (3, 9), (-1, 1)])
def test_quadrat(x, e):
    assert quadrat(x) == e

def test_null():
    assert quadrat(0) == 0

def hilfe():
    assert quadrat(1) == 2
